"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[57891],{3331:(e,a,o)=>{o.d(a,{R:()=>n,x:()=>d});var s=o(36672);const r={},i=s.createContext(r);function n(e){const a=s.useContext(i);return s.useMemo((function(){return"function"==typeof e?e(a):{...a,...e}}),[a,e])}function d(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:n(e.components),s.createElement(i.Provider,{value:a},e.children)}},55084:(e,a,o)=>{o.r(a),o.d(a,{assets:()=>t,contentTitle:()=>d,default:()=>l,frontMatter:()=>n,metadata:()=>s,toc:()=>c});const s=JSON.parse('{"id":"2023/04/13","title":"2023-04-13","description":"Sem\xe1foro: Um Teclado de Corpo Inteiro","source":"@site/i18n/pt/docusaurus-plugin-content-docs/current/2023/04/13.md","sourceDirName":"2023/04","slug":"/2023/04/13","permalink":"/pt/2023/04/13","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/pt/docusaurus-plugin-content-docs//current/2023/04/13.md","tags":[],"version":"current","frontMatter":{"localized_date":"13 de abril de 2023","top_news":"Sem\xe1foro: Um Teclado de Corpo Inteiro"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-14","permalink":"/pt/2023/04/14"},"next":{"title":"2023-04-12","permalink":"/pt/2023/04/12"}}');var r=o(23420),i=o(3331);const n={localized_date:"13 de abril de 2023",top_news:"Sem\xe1foro: Um Teclado de Corpo Inteiro"},d="2023-04-13",t={},c=[{value:"Sem\xe1foro: Um Teclado de Corpo Inteiro",id:"sem\xe1foro-um-teclado-de-corpo-inteiro",level:2},{value:"Mostrar GPT-4-powered web searches para programadores",id:"mostrar-gpt-4-powered-web-searches-para-programadores",level:2},{value:"Substituir os meus melhores amigos por um LLM treinado em 500k mensagens de chat de grupo",id:"substituir-os-meus-melhores-amigos-por-um-llm-treinado-em-500k-mensagens-de-chat-de-grupo",level:2},{value:"NPR sai do Twitter depois de ser rotulada como &#39;m\xeddia filiada ao estado",id:"npr-sai-do-twitter-depois-de-ser-rotulada-como-m\xeddia-filiada-ao-estado",level:2},{value:"Despedimentos em massa e chefes ausentes criam uma crise de moral na Meta",id:"despedimentos-em-massa-e-chefes-ausentes-criam-uma-crise-de-moral-na-meta",level:2},{value:"Hetzner apresenta os Servidores de Nuvem ARM64",id:"hetzner-apresenta-os-servidores-de-nuvem-arm64",level:2},{value:"Novo Director da NASA Jura Juramento sobre o &#39;Pale Blue Dot&#39; de Carl Sagan em vez da B\xedblia",id:"novo-director-da-nasa-jura-juramento-sobre-o-pale-blue-dot-de-carl-sagan-em-vez-da-b\xedblia",level:2},{value:"Intel Foundry Services and Arm anunciam colabora\xe7\xe3o no design do SoC",id:"intel-foundry-services-and-arm-anunciam-colabora\xe7\xe3o-no-design-do-soc",level:2},{value:"O jogador EVE Online usa uma regra obscura para fazer o maior assalto da hist\xf3ria do jogo",id:"o-jogador-eve-online-usa-uma-regra-obscura-para-fazer-o-maior-assalto-da-hist\xf3ria-do-jogo",level:2},{value:"Os fios virtuais chegam em JDK 21, inaugurando uma nova era de concorr\xeancia",id:"os-fios-virtuais-chegam-em-jdk-21-inaugurando-uma-nova-era-de-concorr\xeancia",level:2}];function m(e){const a={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,i.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(a.header,{children:(0,r.jsx)(a.h1,{id:"2023-04-13",children:"2023-04-13"})}),"\n",(0,r.jsx)(a.h2,{id:"sem\xe1foro-um-teclado-de-corpo-inteiro",children:"Sem\xe1foro: Um Teclado de Corpo Inteiro"}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.a,{href:"https://github.com/everythingishacked/Semaphore",children:"Original"}),'.\nSemaphore \xe9 um teclado de corpo inteiro que usa OpenCV e MediaPipe\'s Pose Detection para detectar pontos de refer\xeancia do corpo a partir da entrada de v\xeddeo, calcular diferen\xe7as relativas, e traduzi-las em teclas e comandos enviados via teclado. A entrada principal \xe9 "digitar" letras, d\xedgitos e s\xedmbolos via sem\xe1foro de bandeira, estendendo ambos os bra\xe7os em v\xe1rios \xe2ngulos, com outros gestos modificadores inclu\xeddos para fun\xe7\xf5es tais como teclas shift, backspace, e setas. Funciona no \xfaltimo MacOS e pode ser acedido atrav\xe9s do terminal com a utiliza\xe7\xe3o de uma biblioteca de teclado personalizada.']}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35536550",children:"Discussion Service"}),".\nUm sistema de teclado chamado Semaphore, que utiliza gestos f\xedsicos, recebeu feedback positivo dos utilizadores da Discussion Service e tem implica\xe7\xf5es para os trabalhadores remotos que querem combinar exerc\xedcio f\xedsico e programa\xe7\xe3o. Os utilizadores discutem a combina\xe7\xe3o de Semaphore com estenografia, notas musicais, exerc\xedcios de yoga, e programa\xe7\xe3o, e alguns apontam o potencial para uma maior efici\xeancia atrav\xe9s da adi\xe7\xe3o de caracter\xedsticas como um autocompletar."]}),"\n",(0,r.jsx)(a.h2,{id:"mostrar-gpt-4-powered-web-searches-para-programadores",children:"Mostrar GPT-4-powered web searches para programadores"}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.a,{href:"https://www.phind.com",children:"Original"}),".\nO website 'phind.com' est\xe1 actualmente inacess\xedvel, pois est\xe1 a utilizar um servi\xe7o de seguran\xe7a para se proteger de ataques online que possam ter sido desencadeados por certas ac\xe7\xf5es, tais como submeter uma certa palavra ou frase, um comando SQL, ou dados mal formados. Para resolver isto, os utilizadores podem enviar um e-mail ao propriet\xe1rio do site e incluir detalhes do que estavam a fazer quando o bloqueio ocorreu e o ID do Raio de Nuvem encontrado na parte inferior da p\xe1gina."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35543668",children:"Discussion Service"}),".\nO motor de pesquisa GPT-4 da Phind.com oferece respostas de codifica\xe7\xe3o precisas e explica\xe7\xf5es detalhadas atrav\xe9s de filtros personalizados, e modelos de partilha de receitas t\xeam sido explorados para produtores de conte\xfados, embora haja preocupa\xe7\xf5es sobre os custos de modelagem; os utilizadores elogiaram o servi\xe7o pela sua informa\xe7\xe3o clara, efici\xeancia, e informa\xe7\xe3o suplementar valiosa, embora tenham sido notados alguns problemas de exactid\xe3o de consulta. Alguns utilizadores criticaram a capacidade do GPT-4 para resolver problemas e questionaram a sua exactid\xe3o e relev\xe2ncia, mas a equipa Phind respondeu lan\xe7ando uma nova vers\xe3o com uma funcionalidade Expert mode."]}),"\n",(0,r.jsx)(a.h2,{id:"substituir-os-meus-melhores-amigos-por-um-llm-treinado-em-500k-mensagens-de-chat-de-grupo",children:"Substituir os meus melhores amigos por um LLM treinado em 500k mensagens de chat de grupo"}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.a,{href:"https://www.izzy.co/blogs/robo-boys.html",children:"Original"}),".\nUm LLM foi treinado nas mensagens de chat em grupo n\xe3o censuradas da Izzy Miller na era universit\xe1ria, resultando em melhores conversas com os seus melhores amigos. O conjunto de dados consistia em 500k mensagens, e Miller realizou uma sess\xe3o para facilitar a modela\xe7\xe3o. O modelo resultante gerou conversas inteiras, capturando a ess\xeancia contextual do chat em grupo, e o artigo explica como converter os pesos LLaMA num formato compat\xedvel com a biblioteca de Transformers utilizando a codifica\xe7\xe3o Python, incluindo a import\xe2ncia de um aprovisionamento adequado do espa\xe7o em disco."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35540154",children:"Discussion Service"}),".\nAlguns utilizadores da Discussion Service expressam preocupa\xe7\xe3o sobre as implica\xe7\xf5es \xe9ticas da cria\xe7\xe3o de c\xf3pias digitais de indiv\xedduos utilizando dados pessoais, enquanto outros argumentam que as leis existentes e a press\xe3o moral/social ainda se aplicam. Os cr\xedticos alertam para potenciais aplica\xe7\xf5es nefastas da tecnologia LLM por regimes autocr\xe1ticos ou para fins lucrativos. Debates divisivos sobre a tecnologia da IA surgiram com preocupa\xe7\xf5es sobre o seu impacto n\xe3o testado na privacidade e hipersensibilidade em torno da sua efic\xe1cia. H\xe1 controv\xe9rsia em torno da utiliza\xe7\xe3o de chatbots de IA e do seu potencial para substituir as liga\xe7\xf5es humanas, bem como preocupa\xe7\xf5es \xe9ticas sobre as ferramentas de preenchimento de texto que permitem a cria\xe7\xe3o de simula\xe7\xf5es digitais de entes queridos perdidos."]}),"\n",(0,r.jsx)(a.h2,{id:"npr-sai-do-twitter-depois-de-ser-rotulada-como-m\xeddia-filiada-ao-estado",children:"NPR sai do Twitter depois de ser rotulada como 'm\xeddia filiada ao estado"}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.a,{href:"https://www.wbur.org/npr/1169269161/npr-leaves-twitter-government-funded-media-label",children:"Original"}),'.\nA NPR parou a sua actividade no Twitter depois de os ter rotulado como "meios de comunica\xe7\xe3o social estatais", um r\xf3tulo que a NPR acredita ser impreciso e enganador. Esta decis\xe3o protege a credibilidade da NPR e assegura que podem produzir jornalismo sem negativismo. Elon Musk admitiu que pode ter-se enganado no r\xf3tulo e pode alter\xe1-lo para "financiamento p\xfablico".']}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35539280",children:"Discussion Service"}),'.\nA NPR enfrentou cr\xedticas e acabou por abandonar o Twitter depois de ter sido rotulada como "meios de comunica\xe7\xe3o social estatais" devido ao financiamento do governo, o que levou a um debate sobre os crit\xe9rios para tal rotula\xe7\xe3o e se caracteriza correctamente a NPR como uma organiza\xe7\xe3o noticiosa com independ\xeancia editorial. Alguns utilizadores da Discussion Service sugerem que outras empresas, incluindo as firmas de Elon Musk, se enquadram nesta categoria devido ao financiamento do governo. Os coment\xe1rios tamb\xe9m destacam a complexa rela\xe7\xe3o entre os meios de comunica\xe7\xe3o, fontes de financiamento e independ\xeancia editorial, com algumas acusando a NPR de preconceito de esquerda e outras defendendo a sua transpar\xeancia e independ\xeancia.']}),"\n",(0,r.jsx)(a.h2,{id:"despedimentos-em-massa-e-chefes-ausentes-criam-uma-crise-de-moral-na-meta",children:"Despedimentos em massa e chefes ausentes criam uma crise de moral na Meta"}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.a,{href:"https://www.nytimes.com/2023/04/12/technology/meta-layoffs-employees-management.html",children:"Original"}),".\nO moral est\xe1 em baixo na empresa-m\xe3e do Facebook, Meta, devido a despedimentos em massa e aus\xeancias dos patr\xf5es, o que causa preocupa\xe7\xe3o entre os trabalhadores. A direc\xe7\xe3o da empresa est\xe1 tamb\xe9m a ser questionada pelos trabalhadores."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35537813",children:"Discussion Service"}),".\nOs peritos discutem opini\xf5es diferentes sobre o futuro das tecnologias de ponta como a IA generativa, VR, e a moeda criptogr\xe1fica. Enquanto alguns defendem casos de uso espec\xedfico de IA generativa e avan\xe7os nos meios generativos, s\xe3o levantadas preocupa\xe7\xf5es sobre o seu potencial para automatizar trabalhos da classe m\xe9dia e a precis\xe3o dos modelos de IA generativa. As empresas procuram a IA generativa para ajudar a acelerar o mercado da tecnologia AR/VR, e o sucesso dos dispositivos da Meta Labs \xe9 contrastado com o sucesso incerto dos auscultadores da Apple. A ind\xfastria criptogr\xe1fica \xe9 vista por alguns como um esquema de afinidade, mas a Bitcoin ainda \xe9 vista de forma diferente por outros."]}),"\n",(0,r.jsx)(a.h2,{id:"hetzner-apresenta-os-servidores-de-nuvem-arm64",children:"Hetzner apresenta os Servidores de Nuvem ARM64"}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.a,{href:"https://www.hetzner.com/press-release/arm64-cloud/",children:"Original"}),".\nO fornecedor alem\xe3o de alojamento e nuvem Hetzner lan\xe7ou quatro novos servidores Hetzner Cloud baseados na tecnologia Arm64, marcando a primeira utiliza\xe7\xe3o dos processadores por parte da empresa. Os servidores oferecem at\xe9 16 vCPUs e combinam com at\xe9 32 GB de RAM ECC e at\xe9 320 GB de armazenamento baseado em SSD NVMe. A nova linha de servidores come\xe7a ao pre\xe7o de 3,79 euros ($4,54) por m\xeas, e tem op\xe7\xf5es de factura\xe7\xe3o por hora que ir\xe3o baixar os custos para os clientes."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35540084",children:"Discussion Service"}),".\nHetzner lan\xe7ou o ARM64 cloud servers que s\xe3o menos caros e superam o desempenho do AWS. A infra-estrutura em nuvem tem opini\xf5es mistas, j\xe1 que alguns defendem a fiabilidade e a escalabilidade, enquanto outros acham as configura\xe7\xf5es mais simples mais fi\xe1veis e rent\xe1veis. A oferta da Hetzner preenche uma lacuna para aqueles que querem executar o Docker sem configurar todos os servi\xe7os, mas pode n\xe3o ser adequada para empresas preocupadas com a seguran\xe7a devido a um controlo de acesso f\xedsico mais fraco. Alguns relataram proibi\xe7\xf5es de contas devido \xe0 r\xedgida pol\xedtica de fraude da Hetzner, e existem quest\xf5es sobre a sustentabilidade dos pre\xe7os baixos na Europa devido aos elevados custos de energia."]}),"\n",(0,r.jsx)(a.h2,{id:"novo-director-da-nasa-jura-juramento-sobre-o-pale-blue-dot-de-carl-sagan-em-vez-da-b\xedblia",children:"Novo Director da NASA Jura Juramento sobre o 'Pale Blue Dot' de Carl Sagan em vez da B\xedblia"}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.a,{href:"https://www.independent.co.uk/space/nasa-director-carl-sagan-oath-b2317698.html",children:"Original"}),'.\nMakenzie Lystrup, o recentemente nomeado director do Centro de Voo Espacial Goddard da NASA, fez um juramento n\xe3o convencional usando o livro "Pale Blue Dot" de Carl Sagan de 1994 em vez da B\xedblia. O livro do astr\xf3nomo foi inspirado na famosa fotografia do Pale Blue Dot da Terra tirada em 1990 pela sonda espacial Voyager 1, e Lystrup afirma estar "profundamente focado no crescimento da pr\xf3xima gera\xe7\xe3o de inovadores". A m\xe3o-de-obra do Goddard Space Flight Center \xe9 composta por 10.000 empregados, tanto funcion\xe1rios p\xfablicos como empreiteiros, e o centro \xe9 respons\xe1vel pela execu\xe7\xe3o de uma carteira de 4 mil milh\xf5es de d\xf3lares.']}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35536612",children:"Discussion Service"}),'.\nO novo director da NASA prestou juramento sobre o "Pale Blue Dot" de Carl Sagan, desencadeando um debate sobre a efic\xe1cia dos juramentos, o significado dos textos sagrados, valores pessoais versus textos religiosos, e o verdadeiro significado da responsabilidade pessoal. Alguns argumentam que jurar sobre um livro que representa os pr\xf3prios valores \xe9 mais apropriado, enquanto outros acham necess\xe1rio ter uma representa\xe7\xe3o de uma divindade como fiador do juramento. O juramento tem pap\xe9is ritual\xedsticos e tem sido utilizado para moldar sociedades e hist\xf3ria, mas, em \xfaltima an\xe1lise, o artigo n\xe3o cont\xe9m informa\xe7\xe3o nova ou excitante para especialistas na mat\xe9ria.']}),"\n",(0,r.jsx)(a.h2,{id:"intel-foundry-services-and-arm-anunciam-colabora\xe7\xe3o-no-design-do-soc",children:"Intel Foundry Services and Arm anunciam colabora\xe7\xe3o no design do SoC"}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.a,{href:"https://www.intel.com/content/www/us/en/newsroom/news/intel-foundry-arm-announce-multigeneration-collaboration-leading-edge-soc-design.html",children:"Original"}),".\nA Intel Foundry Services (IFS) e a Arm concordaram com uma colabora\xe7\xe3o multigera\xe7\xf5es para permitir o desenvolvimento de sistemas de computa\xe7\xe3o de baixa pot\xeancia (SoC) para dispositivos m\xf3veis e outras ind\xfastrias. A colabora\xe7\xe3o ir\xe1 permitir a combina\xe7\xe3o dos processadores seguros e energeticamente eficientes da Arm com a pegada de fabrico do IFS que inclui a capacidade baseada nos EUA e na UE, proporcionando novas tecnologias revolucion\xe1rias de trans\xedstores para uma melhor pot\xeancia e desempenho no processo Intel 18A. Esta colabora\xe7\xe3o permitir\xe1 uma cadeia de fornecimento global mais equilibrada para os clientes de fundi\xe7\xe3o que trabalham em n\xfacleos de CPU baseados na Arm."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35539057",children:"Discussion Service"}),".\nA Intel Foundry Services colabora com a Arm para conceber SoCs, enfrentando a concorr\xeancia da TSMC com uma hist\xf3ria de colabora\xe7\xe3o com a Arm. Os utilizadores da Discussion Service discutem os pr\xf3s e os contras do Mac Studio e comparam-no com outras op\xe7\xf5es de PC, com cr\xedticas \xe0s limita\xe7\xf5es do Mac para jogos e software CAD. O artigo e os coment\xe1rios cobrem alternativas para dispositivos e fabrico IOT, a produ\xe7\xe3o de n\xf3s de 2nm da Intel, e especula\xe7\xf5es sobre a capacidade da Intel de cumprir as suas promessas, ao mesmo tempo que reconhecem a import\xe2ncia do consumo de energia, pre\xe7o, e capacidade sem fios no desenvolvimento de dispositivos IOT."]}),"\n",(0,r.jsx)(a.h2,{id:"o-jogador-eve-online-usa-uma-regra-obscura-para-fazer-o-maior-assalto-da-hist\xf3ria-do-jogo",children:"O jogador EVE Online usa uma regra obscura para fazer o maior assalto da hist\xf3ria do jogo"}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.a,{href:"https://www.pcgamer.com/eve-online-player-uses-obscure-rule-to-pull-off-the-biggest-heist-in-the-games-history/",children:"Original"}),'.\nUm jogador EVE Online realizou o maior assalto da hist\xf3ria do jogo, explorando o "mecanismo de ac\xe7\xf5es", resultando num lan\xe7o de mais de $22.300 em dinheiro real. Isto envolveu assumir o controlo da Event Horizon Expeditionaries utilizando uma conta limpa, transferir ac\xe7\xf5es, e retirar a carteira corporativa de 130 mil milh\xf5es de ISK e m\xfaltiplos navios, estimando o valor total do lan\xe7o em 2,23 trili\xf5es de ISK. O sistema de ac\xe7\xf5es \xe9 potencialmente demasiado f\xe1cil de explorar, de acordo com um fio Reddit 2014, e esta estrat\xe9gia j\xe1 foi testada anteriormente.']}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35533711",children:"Discussion Service"}),".\nUm jogador orquestrou um assalto bem sucedido na EVE Online, levantando quest\xf5es em torno da sua mec\xe2nica empresarial e dos riscos de explora\xe7\xe3o do jogo. O assalto foi visto como fixe e um ponto alto do jogo, mas alguns criticam o foco financeiro e a mec\xe2nica do jogo, incluindo o seu valor na moeda do jogo e o seu sistema de vota\xe7\xe3o corporativo."]}),"\n",(0,r.jsx)(a.h2,{id:"os-fios-virtuais-chegam-em-jdk-21-inaugurando-uma-nova-era-de-concorr\xeancia",children:"Os fios virtuais chegam em JDK 21, inaugurando uma nova era de concorr\xeancia"}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.a,{href:"https://www.infoq.com/news/2023/04/virtual-threads-arrives-jdk21/",children:"Original"}),".\nN/A."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35535906",children:"Discussion Service"}),".\nOs fios virtuais do JDK 21 reduzem os fios f\xedsicos para a simultaneidade e simplifica\xe7\xe3o das aplica\xe7\xf5es io-intensivas, mas surgem debates sobre a gest\xe3o da mem\xf3ria. Java \xe9 comparado com Go, e estruturas como Spring, Spring Boot, e Quarkus fornecem alternativas ao Ruby on Rails, enquanto o debate sobre Java versus Go considera o desempenho, a observabilidade, a solidez dos sistemas de tipo, e o interop. O artigo reflecte sobre a categoria JVM de nicho e como diferentes implementa\xe7\xf5es podem afectar a experi\xeancia do utilizador, com compara\xe7\xf5es com C# e JetBrains Rider mencionadas."]})]})}function l(e={}){const{wrapper:a}={...(0,i.R)(),...e.components};return a?(0,r.jsx)(a,{...e,children:(0,r.jsx)(m,{...e})}):m(e)}}}]);